file.content:
{
 "summary": "A Turkish inbound call, already identified by the bank's phone menu, in which the assistant finds the caller's credit card, reads its statement debt per currency (Türk Lirası, Dolar, Euro, İngiliz Sterlini) and the due date, and can then move the statement week or e-mail the latest statement to the registered address; payments, disputes and agent requests go to a human agent, everything else to the main menu.",
 "call_variables": [
  {
   "name": "customerNumber",
   "meaning": "The 8-digit customer number handed over by the phone menu, which has already identified the caller. The agent never asks for it. It is sent as customerNo to cards_list, contact_email_get and statement_pdf_send. (BRIEF.md)"
  },
  {
   "name": "now",
   "meaning": "Date and time of the call in Istanbul time, e.g. 2026-10-12T10:30:00+03:00. Every date decision uses now, never the system clock. (BRIEF.md)"
  }
 ],
 "stages": [
  {
   "id": "card_list",
   "what_happens": "Call cards_list with the customer number. 404 FB_IVR_CHANNEL_102 means no eligible card: say the fixed sentence and go to the main menu. A 500 or timeout is a service failure: agent. One eligible card is taken without a question. More than one goes to card selection.",
   "may_start_only_after": "Call start. No identity check, code, PIN or date of birth is asked.",
   "tools": [
    "cards_list"
   ]
  },
  {
   "id": "card_selection",
   "what_happens": "Ask which card, with at most two example names from the caller's own list. Skip the question if the caller already named a card that fits exactly one. Same name: ask the last four digits. Same last four: ask the last six. Same last six: ask the card number. 'All my cards' is refused, the question is put again and it costs a try. An unknown name: say there is no such card and read the eligible ones again. A supplementary-only card (isMainCard false): say it is not eligible and ask for another. Never confirm the chosen card and never say digits back.",
   "may_start_only_after": "cards_list succeeded with more than one eligible card; or the caller wants another card after a reading or switches card.",
   "tools": []
  },
  {
   "id": "debt_reading",
   "what_happens": "Call cards_balance with cardNumber exactly as cards_list returned it. Read in order: card introduction and closing date, Türk Lirası, Dolar, Euro, İngiliz Sterlini, one no-debt sentence, remaining automatic payment (when it applies), due date. If the top-level statementPaymentStatus is NO_DEBT, use the no-debt reading. If the caller wants only one figure, give only that. If the caller cuts in, stop and go to the offer.",
   "may_start_only_after": "Exactly one card is settled (a single card, or the caller's choice).",
   "tools": [
    "cards_balance"
   ]
  },
  {
   "id": "another_card_question",
   "what_happens": "Ask 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'. Yes: back to card selection and read that card. No, or no cards left: the offer. After a no-debt reading, no or no other card goes to the main menu.",
   "may_start_only_after": "A reading is finished and the caller has more than one eligible card.",
   "tools": []
  },
  {
   "id": "email_lookup",
   "what_happens": "Call contact_email_get to learn whether an e-mail is registered (ibanEmail not empty and communicationType not phone only). An error goes to an agent.",
   "may_start_only_after": "The reading (and the another-card question, when it applies) is done, and before the offer is spoken.",
   "tools": [
    "contact_email_get"
   ]
  },
  {
   "id": "offer",
   "what_happens": "Offer only what the caller can do: week change and e-mail, only week change, only e-mail, or no offer. Route the answer: e-mail, statement week, nothing else (main menu), pay (agent). If debt and e-mail were asked together, skip the offer question and go straight to the e-mail step.",
   "may_start_only_after": "The due date was read, the another-card question is settled and contact_email_get has answered.",
   "tools": []
  },
  {
   "id": "email_statement",
   "what_happens": "Read the registered address (shortened if long or messy, never spelled) and ask permission. On a clear yes call statement_pdf_send with the registered address and the statementDate from cards_balance. On success say the sent sentence, then main menu. No, or 'address not mine': nothing is sent, main menu. Only the latest statement and only the registered address.",
   "may_start_only_after": "contact_email_get returned a registered e-mail and the caller asked for the statement by e-mail.",
   "tools": [
    "statement_pdf_send"
   ]
  },
  {
   "id": "statement_week_current",
   "what_happens": "Call statement_week_get. Say the current week and the next closing and due dates (for a joint statement, both cards), and ask whether to change. No: main menu. Yes: offer the weeks other than the current one. An unoffered week, day or date: read the options again. The current week: nothing needs changing.",
   "may_start_only_after": "The caller asked to change the statement date or week (and the yearly right is not used, where that can be known).",
   "tools": [
    "statement_week_get"
   ]
  },
  {
   "id": "statement_week_preview_confirm",
   "what_happens": "Call statement_week_decide with the chosen week and the current statementDay. For a joint statement, say the other-card sentence first. Then read the new week and preview dates and ask 'Onaylıyor musunuz?'. Only a clear 'evet' counts. A hedged answer: ask again plainly (three tries). No: no change, main menu.",
   "may_start_only_after": "statement_week_get succeeded and the caller picked one of the offered weeks (not the current one).",
   "tools": [
    "statement_week_decide"
   ]
  },
  {
   "id": "statement_week_change",
   "what_happens": "Call statement_week_change once. On success (exitState OK and responseCode 0) say the done sentence with the preview dates, then main menu. An error: the statement week failure sentence and agent.",
   "may_start_only_after": "statement_week_decide succeeded, the preview dates were read and the caller gave a clear 'evet'.",
   "tools": [
    "statement_week_change"
   ]
  },
  {
   "id": "ending",
   "what_happens": "The call ends in one of: main menu, agent, IVR login step, or call closed (third silence), each with its fixed last sentence.",
   "may_start_only_after": "One of the ending conditions listed under endings.",
   "tools": []
  }
 ],
 "not_before": [
  {
   "forbidden": "Calling statement_week_change",
   "until": "statement_week_decide has succeeded, the preview dates have been read and the caller has given a clear 'evet' (insistence such as 'don't ask, just do it' does not lift it)",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §7 step 7: 'Only now, after the preview and the clear yes: statement.week.change'; example-scenarios Example 5"
  },
  {
   "forbidden": "Calling statement_pdf_send",
   "until": "The registered address has been read back and the caller has given a clear yes",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §6.3: 'Only after a clear yes, call statement.pdf.send, and only ever with the registered address.'"
  },
  {
   "forbidden": "Saying the statement was sent ('gönderildi')",
   "until": "statement_pdf_send returns success",
   "applies_to": "agent",
   "source": "example-scenarios Example 4: '\"gönderildi\" [sent] is said only when the service returns success'"
  },
  {
   "forbidden": "Saying the statement week was changed",
   "until": "statement_week_change succeeded (exitState 'OK' and responseCode 0)",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §7 step 8; service contract §5.5: 'Success = exitState \"OK\" and responseCode 0'"
  },
  {
   "forbidden": "Asking 'Onaylıyor musunuz?' on a joint statement",
   "until": "The sentence that the change also affects the other card has been said",
   "applies_to": "agent, when relationType is M or C",
   "source": "2026-10-07 transcript [00:25:28] Elçin: 'Before the question. I want the customer to hear it, and then the question comes.'; 2026-10-08 analysis §7 step 5"
  },
  {
   "forbidden": "Making the offer (week change / e-mail)",
   "until": "The another-card question has been asked and answered (callers with more than one eligible card) and contact_email_get has been called",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §5.1: 'before the offer'; §5.2: 'we call contact.email.get before the offer'"
  },
  {
   "forbidden": "Offering or mentioning the e-mail option",
   "until": "contact_email_get shows a registered e-mail (never, if there is none)",
   "applies_to": "callers with ibanEmail empty or communicationType phone only",
   "source": "2026-10-08 analysis §5.2 and §6.1; example-scenarios Example 6"
  },
  {
   "forbidden": "Offering the statement week change",
   "until": "Never, for a caller who has already used the right this calendar year",
   "applies_to": "callers who used the yearly right",
   "source": "2026-10-08 analysis §7: 'A caller who has used the right this year is not offered the change'; transcript [00:19:51]"
  },
  {
   "forbidden": "Reading any debt",
   "until": "One single card is settled; the debts of several cards are never read together",
   "applies_to": "callers with more than one eligible card",
   "source": "2026-10-08 analysis §3.3 'All of them, please'; example-scenarios Example 3"
  },
  {
   "forbidden": "Transferring an out-of-scope question to the main menu",
   "until": "The caller has answered yes to 'Sizi ana menüye aktarmamı ister misiniz?' (or three tries are used up)",
   "applies_to": "callers asking something outside the flow",
   "source": "2026-10-09 decisions recap item 2: 'doesn't send the caller away straight off'"
  },
  {
   "forbidden": "Transferring an upset caller to an agent for complaining",
   "until": "Three calming replies have been given and the caller is still complaining (an explicit agent request transfers at once)",
   "applies_to": "angry or abusive callers",
   "source": "2026-10-09 decisions recap (Selin): 'Only if they are still complaining after the third one'"
  },
  {
   "forbidden": "Ending the call for silence",
   "until": "The third silence",
   "applies_to": "silent callers",
   "source": "2026-10-09 decisions recap item 1; 2026-10-08 analysis §8.2"
  },
  {
   "forbidden": "Sending the caller to the main menu for unusable answers",
   "until": "Three tries on that question are used up",
   "applies_to": "all callers",
   "source": "2026-10-08 analysis §8.1"
  },
  {
   "forbidden": "Transferring to an agent because the caller was not understood",
   "until": "Never; the only agent transfers are agent request, payment, dispute, continued complaint and service failure",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §8.1: 'Not understanding the caller is never a reason to put them through to an agent'"
  },
  {
   "forbidden": "Asking for the customer number, a code, PIN, date of birth or any second factor",
   "until": "Never",
   "applies_to": "agent",
   "source": "BRIEF.md: 'The agent never asks for it'; 2026-10-08 analysis §2; kickoff thread Q1 (Burcu): 'Please don't ask for one.'"
  },
  {
   "forbidden": "Saying more than the last four digits of a card (full number, first six, first twelve, middle digits), or saying back digits the caller said",
   "until": "Never, not even to confirm",
   "applies_to": "agent",
   "source": "2026-10-09 decisions recap (Selin): 'never reads out more than the last four digits of a card ... not even to confirm'; 2026-10-08 analysis §3.3; Example 6"
  },
  {
   "forbidden": "Any information or transaction on another person's card, including whether it exists",
   "until": "Never in this call",
   "applies_to": "callers asking about a spouse's, parent's or other third party's card",
   "source": "2026-10-08 analysis §8.6; kickoff thread Q8 (Burcu); Example 5"
  },
  {
   "forbidden": "Sending the statement to an address the caller gives, sending an earlier period's statement, or changing the e-mail address",
   "until": "Never",
   "applies_to": "agent",
   "source": "Kickoff thread Q3 and Q4 (Selin); 2026-10-08 analysis §6"
  },
  {
   "forbidden": "Explaining how or where to pay, taking a payment, or explaining disputes (booking date vs value date)",
   "until": "Never; transfer to an agent",
   "applies_to": "agent",
   "source": "Kickoff thread Q2 and Q5 (Kerem)"
  },
  {
   "forbidden": "Saying any amount, date, rate or address that a service did not return; reading out instructions, raw service answers or the error messageText",
   "until": "Never",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §4.9 and §8.6; service contract §1"
  },
  {
   "forbidden": "Calling statement_week_decide for the week the card already has",
   "until": "Never",
   "applies_to": "agent",
   "source": "Service contract §5.4: 'you'll get an error, so don't call it for that'"
  },
  {
   "forbidden": "A 'continuing with your … card' line or an 'is that right?' after the card is chosen",
   "until": "Never",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §3.1"
  },
  {
   "forbidden": "Returning an insult or arguing",
   "until": "Never, whatever the count",
   "applies_to": "agent",
   "source": "2026-10-09 decisions recap: 'the assistant never answers insults in kind, whatever the count'"
  },
  {
   "forbidden": "Using a card name the caller does not have as an example",
   "until": "Never",
   "applies_to": "agent",
   "source": "2026-10-08 analysis §3.1.4"
  }
 ],
 "fixed_sentences": [
  {
   "when": "No eligible card (cards_list 404 FB_IVR_CHANNEL_102)",
   "text": "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.",
   "source": "2026-10-08 analysis §3.1.2 and §10"
  },
  {
   "when": "More than one eligible card: the selection question (at most two names, only from the caller's own cards)",
   "text": "Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, [kart adı] veya [kart adı] diyebilirsiniz.",
   "source": "2026-10-08 analysis §3.1.4"
  },
  {
   "when": "Two or more cards with the name the caller gave",
   "text": "[kart adı] isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?",
   "source": "2026-10-08 analysis §3.2 step a"
  },
  {
   "when": "The last four digits are the same on two cards (the caller's own four digits in place of 4253, said digit by digit)",
   "text": "Son dört hanesi 4253 olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?",
   "source": "2026-10-09 decisions recap item 4; 2026-10-08 analysis §3.2 step b"
  },
  {
   "when": "The last six digits are the same as well",
   "text": "Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?",
   "source": "2026-10-09 decisions recap item 4; 2026-10-08 analysis §3.2 step c"
  },
  {
   "when": "Opening of every reading; the closing date goes in front of the first currency that is read (the first foreign currency if there is no Türk Lirası debt)",
   "text": "Sonu [son 4 hane] ile biten [kart adı] kartınıza ait [hesap kesim tarihi] tarihinde kesilen ekstre Türk Lirası borcunuz …",
   "source": "2026-10-08 analysis §4.2"
  },
  {
   "when": "The product name is empty",
   "text": "Sonu 4253 ile biten kartınıza ait …",
   "source": "2026-10-08 analysis §3.3; kickoff thread Q12"
  },
  {
   "when": "Türk Lirası, nothing paid (the source writes 'TL'; §4.9 requires the full name)",
   "text": "Türk Lirası borcunuz XXX Türk Lirası, ödenmesi gereken minimum tutar ZZZ Türk Lirası'dır.",
   "source": "2026-10-08 analysis §4.3 with §4.9"
  },
  {
   "when": "Türk Lirası, minimum or more paid",
   "text": "Türk Lirası borcunuz XXX Türk Lirası, kalan toplam borcunuz YYY Türk Lirası'dır. Minimum ödemenizi yaptığınız için teşekkür ederiz.",
   "source": "2026-10-08 analysis §4.3 with §4.9"
  },
  {
   "when": "Türk Lirası, less than the minimum paid",
   "text": "Türk Lirası borcunuz XXX Türk Lirası, ödenmesi gereken minimum tutar ZZZ Türk Lirası, kalan toplam borcunuz YYY Türk Lirası, kalan minimum ödeme tutarınız TTT Türk Lirası'dır.",
   "source": "2026-10-08 analysis §4.3 with §4.9"
  },
  {
   "when": "Foreign currency with debt, in the order Dolar, Euro, İngiliz Sterlini (same sentence with each currency's own full name; the source writes the code 'USD')",
   "text": "Dolar borcunuz XXX Dolar, kalan toplam borcunuz YYY Dolar, ödenmesi gereken minimum tutar ZZZ Dolar'dır.",
   "source": "2026-10-08 analysis §4.4 with §4.9"
  },
  {
   "when": "Currencies with no debt, one sentence after the foreign currency lines (14 fixed sentences in the §4.5 table)",
   "text": "[Türk Lirası / Dolar / Euro / İngiliz Sterlini, joined with ', ' and 've'] borcunuz bulunmamaktadır.",
   "source": "2026-10-08 analysis §4.5, e.g. 'Dolar, Euro ve İngiliz Sterlini borcunuz bulunmamaktadır.'"
  },
  {
   "when": "Due date, after the currency lines",
   "text": "Borçlarınız için son ödeme tarihiniz [son ödeme tarihi]'dir.",
   "source": "2026-10-08 analysis §4.8"
  },
  {
   "when": "The due date is today",
   "text": "Borçlarınız için son ödeme tarihiniz bugündür.",
   "source": "2026-10-08 analysis §4.8"
  },
  {
   "when": "The card's statementPaymentStatus is NO_DEBT",
   "text": "Sonu [son 4 hane] ile biten [kart adı] kartınızın [hesap kesim tarihi] tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz GGG Türk Lirası'dır. Son ödeme tarihiniz [son ödeme tarihi] olacaktır.",
   "source": "2026-10-08 analysis §4.7 with §4.9"
  },
  {
   "when": "The call is on the day the statement is cut (the source says 'Something like')",
   "text": "Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.",
   "source": "2026-10-08 analysis §4.10"
  },
  {
   "when": "After a reading, when the caller has more than one eligible card",
   "text": "Başka bir kartınızın borcunu öğrenmek ister misiniz?",
   "source": "2026-10-08 analysis §5.1"
  },
  {
   "when": "Offer: registered e-mail and week change possible",
   "text": "Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.",
   "source": "2026-10-08 analysis §5.2"
  },
  {
   "when": "Offer: no registered e-mail, week change possible",
   "text": "Hesap kesim tarihinizi değiştirebilirim.",
   "source": "2026-10-08 analysis §5.2"
  },
  {
   "when": "Offer: registered e-mail, week change not possible",
   "text": "Ekstrenizi kayıtlı mail adresinize gönderebilirim.",
   "source": "2026-10-08 analysis §5.2"
  },
  {
   "when": "The caller asks for e-mail but none is registered",
   "text": "Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.",
   "source": "2026-10-08 analysis §6.1"
  },
  {
   "when": "Before sending: read the registered address and ask",
   "text": "Ekstrenizi … adresine göndermemi ister misiniz?",
   "source": "Kickoff thread Q3 (Selin); 2026-10-08 analysis §6.2"
  },
  {
   "when": "statement_pdf_send succeeded",
   "text": "Ekstreniz kayıtlı e-posta adresinize gönderildi.",
   "source": "2026-10-08 analysis §6.4"
  },
  {
   "when": "Optional, before the week question; also the explanation when the right is already used this year",
   "text": "Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz.",
   "source": "2026-10-08 analysis §7"
  },
  {
   "when": "After statement_week_get: current state and question",
   "text": "[kart adı] kartınızın hesap kesim tarihi her ayın [hafta]. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz [tarih], son ödeme tarihiniz [tarih]. Hesap kesim tarihinizi değiştirmek ister misiniz?",
   "source": "2026-10-08 analysis §7 step 2"
  },
  {
   "when": "Week options, without the current week (example for a card in week 2)",
   "text": "Hesap kesim tarihinizi ayın 1., 3. ya da 4. haftasına alabilirim. Hangisini tercih edersiniz?",
   "source": "2026-10-08 analysis §7 step 3"
  },
  {
   "when": "Joint statement, caller holds the main card, before the confirm question",
   "text": "Bu değişiklik kartınıza bağlı [bağlı kart adı] kartınızı da etkileyecek.",
   "source": "2026-10-08 analysis §7 step 5; transcript [00:20:48]"
  },
  {
   "when": "Joint statement, caller holds the linked card, before the confirm question (given as 'e.g.')",
   "text": "Bu değişiklik kartınızın bağlı olduğu [asıl kart adı] kartınızı da etkileyecek.",
   "source": "2026-10-08 analysis §7 step 5"
  },
  {
   "when": "Confirm question with the preview dates (the week number is the chosen week)",
   "text": "Yeni hesap kesim haftanız her ayın 3. haftası olacak. Yeni hesap kesim tarihiniz [tarih], son ödeme tarihiniz [tarih] olacak. Onaylıyor musunuz?",
   "source": "2026-10-08 analysis §7 step 6"
  },
  {
   "when": "statement_week_change succeeded (dates from the preview)",
   "text": "Sonu [son 4 hane] ile biten [kart adı] kartınızın hesap kesim haftası her ayın 3. haftası olarak değiştirildi. Yeni hesap kesim tarihiniz [tarih], son ödeme tarihiniz [tarih].",
   "source": "2026-10-08 analysis §7 step 8"
  },
  {
   "when": "Any statement week service fails",
   "text": "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.",
   "source": "2026-10-08 analysis §7 step 1 and §10"
  },
  {
   "when": "Any other bank service fails (card list, balance, e-mail lookup, PDF send)",
   "text": "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.",
   "source": "2026-10-08 analysis §8.3; transcript [00:26:36]"
  },
  {
   "when": "A service is slow",
   "text": "Bilgilerinizi kontrol ediyorum.",
   "source": "2026-10-08 analysis §8.3"
  },
  {
   "when": "Normal end: nothing else, thanks, goodbye; e-mail sent or declined; week changed or declined; another transaction mid-flow",
   "text": "Sizi ana menüye yönlendiriyorum.",
   "source": "2026-10-08 analysis §8.4 and §10"
  },
  {
   "when": "Three tries used up on any question",
   "text": "Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.",
   "source": "2026-10-09 decisions recap item 3; 2026-10-08 analysis §8.1"
  },
  {
   "when": "A question outside the flow (loan rates, branch hours, limit, points …)",
   "text": "Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?",
   "source": "2026-10-09 decisions recap item 2"
  },
  {
   "when": "Third silence",
   "text": "Sesinizi alamadığım için görüşmeyi sonlandırıyorum.",
   "source": "2026-10-09 decisions recap item 1; 2026-10-08 analysis §8.2"
  },
  {
   "when": "The caller does not speak Turkish",
   "text": "Sizi ana menüye aktarıyorum.",
   "source": "2026-10-08 analysis §8.4; kickoff thread Q10"
  },
  {
   "when": "The caller asks for a person at any point, or is still complaining after the third calming reply",
   "text": "Sizi müşteri temsilcimize aktarıyorum.",
