 "calculations": [
  {
   "name": "service_success",
   "rule": "Success is HTTP 200 and result.returnCode '1'. Anything else is an error, and an error answer has no data object. statement_week_change success is exitState 'OK' and responseCode 0. statement_pdf_send success is exitState 'DONE'. statement_week_decide responseCode 0 means fine.",
   "inputs": [
    "result.returnCode",
    "data.exitState",
    "data.responseCode"
   ],
   "source": "Service contract §3, §5.4, §5.5; test-customers.md"
  },
  {
   "name": "card_count_branch",
   "rule": "cards_list 404 FB_IVR_CHANNEL_102 means no eligible card (not a failure). One eligible card (exitState '1_CARD' / validCardsCount 1) is taken without a question. More than one (exitState 'MULTI_CARD') goes to the selection question. A card with isMainCard false is supplementary and not eligible.",
   "inputs": [
    "cards_list data.cards",
    "data.validCardsCount",
    "data.exitState",
    "cards[].isMainCard"
   ],
   "source": "2026-10-08 analysis §2, §3.1, §3.3; service contract §5.1"
  },
  {
   "name": "card_disambiguation",
   "rule": "If the name fits exactly one card, take it. Two or more with the same name: ask the last four. Same last four: ask the last six. Same last six: ask the card number. Map digits however they are spoken ('kırk iki elli üç' = 4253). Send cardNumber exactly as cards_list returned it, never rebuilt from the caller's digits.",
   "inputs": [
    "cards[].productName",
    "cards[].cardNumberLast4",
    "cards[].cardNumber",
    "caller's digits"
   ],
   "source": "2026-10-08 analysis §3.2, §3.3; 2026-10-09 recap item 4; service contract §5"
  },
  {
   "name": "statement_debt_or_no_debt",
   "rule": "If the top-level statementPaymentStatus of cards_balance is NO_DEBT, use the no-debt reading (§4.7). Otherwise use the normal reading.",
   "inputs": [
    "cards_balance data.statementPaymentStatus"
   ],
   "source": "2026-10-08 analysis §4.7"
  },
  {
   "name": "turkish_lira_case",
   "rule": "From debtTL: remainingDebt 0.00 or below means no Türk Lirası debt (skip it; it goes into the no-debt sentence). remainingMinPayment > 0 and equal to or above minPayment means nothing paid. remainingDebt > 0 and remainingMinPayment 0 or less means minimum or more paid. remainingMinPayment > 0 and below minPayment means less than the minimum paid. XXX = statementDebt, ZZZ = minPayment, YYY = remainingDebt, TTT = remainingMinPayment.",
   "inputs": [
    "debtTL.statementDebt",
    "debtTL.minPayment",
    "debtTL.remainingDebt",
    "debtTL.remainingMinPayment"
   ],
   "source": "2026-10-08 analysis §4.3"
  },
  {
   "name": "currency_has_debt",
   "rule": "A currency at exactly 0,00 or with a minus figure counts as clear and goes into the no-debt sentence; a minus is never read as debt. A currency whose block is missing or empty is left out of the no-debt sentence. Foreign currencies have no paid / not-paid split: XXX statementDebt, YYY remainingDebt, ZZZ minPayment.",
   "inputs": [
    "debtTL",
    "debtUSD",
    "debtEUR",
    "debtGBP"
   ],
   "source": "2026-10-08 analysis §4.4, §4.5, §4.10; service contract §5.2"
  },
  {
   "name": "no_debt_sentence",
   "rule": "One sentence listing every present currency with no debt, in the order Türk Lirası, Dolar, Euro, İngiliz Sterlini, joined with ', ' and 've', followed by 'borcunuz bulunmamaktadır.'. Nothing is said if all four owe. It is not used if none of the four has statement debt (that is the no-debt reading).",
   "inputs": [
    "per-currency debt status",
    "block presence"
   ],
   "source": "2026-10-08 analysis §4.5"
  },
  {
   "name": "reading_order",
   "rule": "1 card introduction and closing date; 2 Türk Lirası; 3 Dolar, Euro, İngiliz Sterlini; 4 no-debt sentence; 5 remaining automatic payment; 6 due date; 7 another-card question; 8 the offer.",
   "inputs": [
    "cards_balance data"
   ],
   "source": "2026-10-08 analysis §4.1"
  },
  {
   "name": "remaining_automatic_payment",
   "rule": "Read only when the due date has passed, automaticPaymentFlag is 'Y' and remainAutomaticPaymentAmount is above zero. Say how much is still to be taken, in Türk Lirası, after the no-debt sentence and before the due date.",
   "inputs": [
    "now",
    "lastPayDate",
    "automaticPaymentFlag",
    "remainAutomaticPaymentAmount"
   ],
   "source": "2026-10-08 analysis §4.6"
  },
  {
   "name": "date_position_of_call",
   "rule": "Compare now with the dates from cards_balance. Due date equal to today: the 'bugündür' sentence. Call on the day the statement is cut: say the cut is today at 00.00, then give the total debt. From the cut date up to the due date: the normal reading. After the due date: say it has passed, then give the total debt. A card with no statement yet: say there is no debt and invent no date.",
   "inputs": [
    "now",
    "statementDate",
    "lastPayDate",
    "nextStatementDate"
   ],
   "source": "2026-10-08 analysis §4.8, §4.10; BRIEF.md ('Every date decision uses now')"
  },
  {
   "name": "speech_formats",
   "rule": "Currency names in full, never codes (TL = Türk Lirası, USD = Dolar, EUR = Euro, GBP = İngiliz Sterlini). Lira and kuruş in full; zero kuruş is not said. Foreign decimals as sent (Dolar, Euro) and peni (İngiliz Sterlini). Dates dd.MM.yyyy become day, month name, year ('21 Ekim 2025'). Last four digits one by one ('dört iki beş üç', never 'kırk iki elli üç' or 'çift sıfır'). Amounts exactly as returned, no rounding. Week ordinal as a word.",
   "inputs": [
    "amounts",
    "dates",
    "cardNumberLast4"
   ],
   "source": "2026-10-08 analysis §4.9; 2026-10-09 recap item 6; IVR prompt sheet ops note on week_ordinal"
  },
  {
   "name": "offer_options",
   "rule": "No registered e-mail means ibanEmail is empty or communicationType is phone only (check the field, not only the type). Offer both, week only, e-mail only, or nothing, according to the registered e-mail and whether the week change is still possible this year.",
   "inputs": [
    "contact_email_get data.ibanEmail",
    "data.communicationType",
    "yearly week-change right"
   ],
   "source": "2026-10-08 analysis §5.2; service contract §5.6"
  },
  {
   "name": "week_options",
   "rule": "Offer weeks 1 to 4 without the card's current statementWeek. The caller's current week: nothing needs changing. A day, date or unoffered week: read the options again.",
   "inputs": [
    "statement_week_get data.statementWeek"
   ],
   "source": "2026-10-08 analysis §7 step 3"
  },
  {
   "name": "week_preview_and_change_inputs",
   "rule": "statement_week_decide and statement_week_change are sent cardNumber, newStatementWeek (the chosen week) and statementDay (the card's current statementDay from statement_week_get). The dates told to the caller before and after the change are statementDate and statementDueDate from statement_week_decide; ignore statementDay in the change answer.",
   "inputs": [
