    "chosen week",
    "statement_week_decide data.statementDate",
    "data.statementDueDate"
   ],
   "source": "Service contract §5.4, §5.5; 2026-10-08 analysis §7 steps 4 and 8"
  },
  {
   "name": "joint_statement",
   "rule": "relationType empty: own statement. 'M': this is the main card of a pair. 'C': this is the linked card. For M or C, read both cards at the current-state step (last four, name, week, next closing and due date) and say the other-card sentence before the confirm question, using relatedCardProductName.",
   "inputs": [
    "statement_week_get data.relationType",
    "data.relatedCardProductName",
    "data.relatedCardNumber"
   ],
   "source": "Service contract §5.3; 2026-10-08 analysis §7 steps 2 and 5"
  },
  {
   "name": "statement_week_change_right",
   "rule": "One change per calendar year, per card; January first resets.",
   "inputs": [
    "now",
    "date of the last change (no service returns it)"
   ],
   "source": "Transcript [00:18:24]–[00:18:50] (Kerem); 2026-10-08 analysis §7"
  },
  {
   "name": "pdf_send_inputs",
   "rule": "customerNo is the call variable. cardNumber is as cards_list returned it. statementDate is the statementDate from cards_balance (the issued statement). emailAddress is only the registered ibanEmail.",
   "inputs": [
