        messy = len(em) > 32 or seps > 1 or any([ch.isdigit() for ch in local])
        if not messy:
            return em + ' adresine'
        lab = dom.split('.')[0]
        lab = lab[:1].upper() + lab[1:]
        return local[:1].lower() + ' ile başlayan ' + lab + ' adresinize'

